from heapq import heappush, heappop


def earliest_arrival(
    n_depots: int,
    legs: list[tuple[int, int, int, int, int, int, bool]],
    origin: int,
    target: int,
    start_time: int,
    max_premium: int,
    min_transfer: int,
) -> tuple[int, int] | None:
    if origin == target:
        return (start_time, 0)

    layers = max_premium + 1

    # adjacency list: depot -> outgoing legs
    adj = [[] for _ in range(n_depots)]

    # Safe finite sentinel bound:
    # any stored "ready to depart" time is either start_time or
    # departure + duration + min_transfer, and departure <= last_departure.
    max_bound = start_time

    for u, v, first, period, last, duration, premium in legs:
        adj[u].append((v, first, period, last, duration, 1 if premium else 0))
        bound = last + duration + min_transfer
        if bound > max_bound:
            max_bound = bound

    INF = max_bound + 1

    # dist[depot * layers + premium_used] = earliest ready-to-depart time
    dist = [INF] * (n_depots * layers)
    dist[origin * layers] = start_time

    # heap entries: (ready_time, premium_used, depot)
    heap = [(start_time, 0, origin)]
    push = heappush
    pop = heappop

    best_arrival = None
    best_premium = layers

    while heap:
        t, used, u = pop(heap)

        # Since duration >= 1, once the smallest ready time is at least the
        # best known target arrival, no later expansion can improve it.
        if best_arrival is not None and t >= best_arrival:
            break

        idx = u * layers + used
        if t != dist[idx]:
            continue

        for v, first, period, last, duration, prem in adj[u]:
            used2 = used + prem
            if used2 >= layers:
                continue

            # Find the earliest departure of this leg at or after time t.
            if period == 0:
                if t > first:
                    continue
                dep = first
            else:
                if t <= first:
                    dep = first
                else:
                    dep = first + ((t - first + period - 1) // period) * period
                    if dep > last:
                        continue

            arr = dep + duration

            if v == target:
                if (
                    best_arrival is None
                    or arr < best_arrival
                    or (arr == best_arrival and used2 < best_premium)
                ):
                    best_arrival = arr
                    best_premium = used2
            else:
                ready = arr + min_transfer

                # This state cannot lead to an arrival better than current best.
                if best_arrival is not None and ready >= best_arrival:
                    continue

                idx2 = v * layers + used2
                if ready < dist[idx2]:
                    dist[idx2] = ready
                    push(heap, (ready, used2, v))

    if best_arrival is None:
        return None

    return (best_arrival, best_premium)
